import { it } from 'vitest'
import net from 'node:net'
import fs from 'node:fs'
import path from 'node:path'
import { randomUUID } from 'node:crypto'
import { deriveBackgroundTasks } from './mobile-background-tasks'

function call(method: string, params: unknown): Promise<any> {
  const m = JSON.parse(fs.readFileSync(path.join(process.env.HOME!, 'Library/Application Support/orca/orca-runtime.json'), 'utf8'))
  const u = m.transports.find((t: any) => t.kind === 'unix')
  return new Promise((res, rej) => {
    const s = net.createConnection(u.endpoint); let b = ''
    s.setEncoding('utf8'); s.on('error', rej)
    s.on('data', (c) => { b += c; let i; while ((i = b.indexOf('\n')) !== -1) { const l = b.slice(0, i); b = b.slice(i + 1); if (!l.trim()) continue; const f = JSON.parse(l); if (f._keepalive) continue; s.end(); f.ok === false ? rej(new Error(f.error?.message)) : res(f) } })
    s.on('connect', () => s.write(JSON.stringify({ id: randomUUID(), authToken: m.authToken, method, params }) + '\n'))
  })
}

